/**
 * Repair List Page
 *
 * Shows all active repairs with status color-coding, customer name, bicycle info,
 * assigned worker, planned date, and pickup date. Managers can filter by status,
 * assigned worker, and pickup date (today/this week). Default sorting is by
 * planned_date descending (most urgent first).
 */

import { useState, useEffect, useCallback, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Calendar,
  ChevronDown,
  Plus,
  User,
  Wrench,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/shared/lib/utils'
import { STATUS_COLORS, type RepairStatus, type RepairDetailWithCustomer } from '../types.js'
import type { RepairDetailResponse } from '../api.js'
import { useRepairDetailCache } from '../hooks/useRepairDetailCache.js'
import { RepairIntakeModal } from './RepairIntakeModal.js'
import { RepairCalendarView } from './RepairCalendarView.js'
import { RepairRowExpandPanel } from './RepairRowExpandPanel.js'
import {
  FilterBar,
  type PickupDateFilterValue,
  type StatusFilterValue,
  type WorkerNameMap,
  UNASSIGNED_WORKER_ID,
} from './FilterBar.js'

// ---------------------------------------------------------------------------
// Types for API response and filter options
// ---------------------------------------------------------------------------

interface PaginatedRepairs {
  repairs: RepairDetailWithCustomer[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

interface RepairListFilters {
  status?: RepairStatus | ''
  assignedTo?: string | 'unassigned'
  pickupDate?: 'today' | 'this_week'
}

// ---------------------------------------------------------------------------
// API function — fetches paginated repair list with filters
// ---------------------------------------------------------------------------

async function fetchRepairs(
  filters: RepairListFilters,
  page: number = 1,
): Promise<PaginatedRepairs> {
  const params = new URLSearchParams()

  if (filters.status) params.set('status', filters.status)
  if (filters.assignedTo === 'unassigned') params.set('assignedTo', 'unassigned')
  else if (filters.assignedTo) params.set('assignedTo', filters.assignedTo)
  if (filters.pickupDate) params.set('pickupDate', filters.pickupDate)
  params.set('page', String(page))

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs list')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Helper — format date for display
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  const d = new Date(epochMs)
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
}

// ---------------------------------------------------------------------------
// Helper — get worker name (simplified; in production this would fetch from users API)
// ---------------------------------------------------------------------------

function getWorkerName(assignedTo: string | null, workers: WorkerOption[]): string {
  if (!assignedTo) return 'Unassigned'
  const worker = workers.find((w) => w.id === assignedTo)
  return worker?.name ?? 'Unknown'
}

interface WorkerOption {
  id: string
  name: string
}

// ---------------------------------------------------------------------------
// View mode type
// ---------------------------------------------------------------------------

type ViewMode = 'list' | 'calendar'

// ---------------------------------------------------------------------------
// Component — Repair List Page
// ---------------------------------------------------------------------------

export function RepairListPage() {
  const navigate = useNavigate()
  const [viewMode, setViewMode] = useState<ViewMode>('list')
  const [repairs, setRepairs] = useState<RepairDetailWithCustomer[]>([])
  const [totalPages, setTotalPages] = useState(1)
  const [currentPage, setCurrentPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Inline expand state — which row is currently expanded (null = none).
  const [expandedId, setExpandedId] = useState<string | null>(null)

  // Detail cache + loader for the expanded row
  const { detailCache, detailLoading, detailError, loadDetail } = useRepairDetailCache()

  // Filter state
  const [filters, setFilters] = useState<RepairListFilters>({
    status: undefined,
    assignedTo: undefined,
    pickupDate: undefined,
  })

  // Workers list (would come from users API in production)
  const [workers, setWorkers] = useState<WorkerOption[]>([])

  // Intake modal open state
  const [showIntakeModal, setShowIntakeModal] = useState(false)

  // Fetch repairs on filter/page change
  const loadRepairs = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const result = await fetchRepairs(filters, currentPage)
      setRepairs(result.repairs)
      setTotalPages(result.totalPages)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load repairs')
    } finally {
      setLoading(false)
    }
  }, [filters, currentPage])

  // Load workers list
  useEffect(() => {
    fetch('/api/users')
      .then((r) => r.json())
      .then((data: WorkerOption[]) => setWorkers(data))
      .catch(() => setWorkers([]))
  }, [])

  // Initial load and filter changes
  useEffect(() => {
    loadRepairs()
  }, [loadRepairs])

  // -------------------------------------------------------------------------
  // Filter wiring — bridge between the page-level `RepairListFilters` state
  // (kept exactly as before — drives the /api/repairs query string) and the
  // new `<FilterBar>` controlled API (which uses `'all'` instead of `''` and
  // `null` instead of `undefined`).
  // -------------------------------------------------------------------------
  const hasActiveFilters = filters.status || filters.assignedTo || filters.pickupDate

  const filterBarStatus: StatusFilterValue = (filters.status || 'all') as StatusFilterValue
  const filterBarAssignedTo: string | null = filters.assignedTo ?? null
  const filterBarPickupDate: PickupDateFilterValue = (filters.pickupDate ||
    'all') as PickupDateFilterValue

  // workerMap prepended with the synthetic "Unassigned" entry so the combobox
  // can display and pick it like any other worker.
  const workerMap: WorkerNameMap = useMemo(() => {
    const map: WorkerNameMap = { [UNASSIGNED_WORKER_ID]: 'Unassigned' }
    for (const w of workers) {
      map[w.id] = w.name
    }
    return map
  }, [workers])

  const handleFilterBarChange = (next: {
    status?: StatusFilterValue
    assignedTo?: string | null
    pickupDate?: PickupDateFilterValue
  }) => {
    setFilters((prev) => ({
      status:
        next.status === undefined
          ? prev.status
          : next.status === 'all'
            ? undefined
            : next.status,
      assignedTo:
        next.assignedTo === undefined
          ? prev.assignedTo
          : next.assignedTo === null
            ? undefined
            : next.assignedTo,
      pickupDate:
        next.pickupDate === undefined
          ? prev.pickupDate
          : next.pickupDate === 'all'
            ? undefined
            : next.pickupDate,
    }))
    setCurrentPage(1) // Reset to first page when filters change
  }

  // -------------------------------------------------------------------------
  // Row expand — toggle inline detail on click, lazy-load on first expand.
  // The "Open repair" button is the only path from the list to /repairs/:id
  // (row click is expand-only, per #265).
  // -------------------------------------------------------------------------
  const handleRowClick = useCallback(
    (id: string) => {
      setExpandedId((prev) => {
        const next = prev === id ? null : id
        // Fire-and-forget fetch for the newly-expanded row. Subsequent
        // expands of the same id reuse the cache; collapse does nothing.
        if (next && !detailCache.has(next) && !detailLoading.has(next)) {
          void loadDetail(next)
        }
        return next
      })
    },
    [detailCache, detailLoading, loadDetail],
  )

  const handleOpenRepair = useCallback(
    (id: string) => {
      navigate(`/repairs/${id}`)
    },
    [navigate],
  )

  // -------------------------------------------------------------------------
  // KPIs — derived client-side from the currently-loaded repairs array.
  // No extra API call: the table already holds the list in scope.
  // -------------------------------------------------------------------------
  const kpis = useMemo(() => {
    const now = Date.now()
    let active = 0
    let inProgress = 0
    let ready = 0
    let overdue = 0
    for (const r of repairs) {
      active++
      if (r.status === 'in_progress') inProgress++
      if (r.status === 'ready') ready++
      if (
        r.plannedDate != null &&
        r.plannedDate < now &&
        r.status !== 'completed' &&
        r.status !== 'cancelled'
      ) {
        overdue++
      }
    }
    return { active, inProgress, ready, overdue }
  }, [repairs])

  return (
    <div className="dashboard-bg -m-6 min-h-full space-y-5 p-5 sm:p-7 lg:p-8">
      {/* Atmospheric glow orbs — match sales page */}
      <div className="glow-orb glow-orb-cyan" aria-hidden />
      <div className="glow-orb glow-orb-violet" aria-hidden />
      <div className="glow-orb glow-orb-blue" aria-hidden />

      {/* ── Hero header (sales-style) ─────────────────────────────── */}
      <header className="relative z-[1] animate-hero-reveal">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
          <div>
            <div className="mb-2 flex items-center gap-2">
              <span className="text-[10px] font-bold uppercase tracking-[.2em] text-cyan-400/70">
                Repairs
              </span>
              <span className="h-px w-8 bg-gradient-to-r from-cyan-400/60 to-transparent" />
            </div>
            <h1 className="bg-gradient-to-r from-cyan-300 via-blue-300 to-violet-300 bg-clip-text text-4xl font-extrabold tracking-tight text-transparent sm:text-[2.5rem] sm:leading-none">
              Repairs
            </h1>
            <p className="mt-2 text-sm text-muted-foreground/80">
              Track active jobs, monitor progress, and prep pickups.
            </p>
            <div className="mt-3 h-px w-40 animated-underline" aria-hidden />
          </div>

          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowIntakeModal(true)}
            className="self-start gap-2 rounded-full border-cyan-400/30 bg-cyan-500/15 px-4 text-[12px] font-semibold tracking-wide text-cyan-200 ring-1 ring-cyan-400/20 hover:border-cyan-400/50 hover:bg-cyan-500/25 hover:text-cyan-100 lg:self-end"
          >
            <Plus size={14} strokeWidth={2.4} />
            Add Repair
          </Button>
        </div>
      </header>

      {/* ── KPI strip ────────────────────────────────────────────── */}
      <section
        className="relative z-[1] grid grid-cols-2 gap-4 lg:grid-cols-4 stagger-children"
        aria-label="Repairs summary"
      >
        <KpiCard
          label="Active"
          value={String(kpis.active)}
          sub={repairs.length === 0 ? 'in view' : 'in view'}
          accent="cyan"
        />
        <KpiCard
          label="In progress"
          value={String(kpis.inProgress)}
          sub={repairs.length === 0 ? 'in view' : 'in view'}
          accent="violet"
        />
        <KpiCard
          label="Ready for pickup"
          value={String(kpis.ready)}
          sub={repairs.length === 0 ? 'in view' : 'in view'}
          accent="emerald"
        />
        <KpiCard
          label="Overdue"
          value={String(kpis.overdue)}
          sub={repairs.length === 0 ? 'in view' : 'past planned date'}
          accent="rose"
        />
      </section>

      {/* ── Filter bar (sales-style glass card) ─────────────────── */}
      <section
        className="relative z-[1] glass-card glass-card-accent overflow-hidden p-4 animate-fade-in-up"
        style={{ animationDelay: '.1s' }}
        aria-label="Repairs filters"
      >
        <div
          className="absolute inset-0 rounded-2xl bg-gradient-to-br from-cyan-500/[.03] via-transparent to-violet-500/[.03] pointer-events-none"
          aria-hidden
        />
        <div className="relative z-[1]">
          <FilterBar
            status={filterBarStatus}
            assignedTo={filterBarAssignedTo}
            pickupDate={filterBarPickupDate}
            workerMap={workerMap}
            onChange={handleFilterBarChange}
          />
        </div>
      </section>

      {/* View Toggle — List | Calendar */}
      <div className="flex gap-1 mb-4" role="tablist">
        <button
          role="tab"
          aria-selected={viewMode === 'list'}
          onClick={() => setViewMode('list')}
          className={`px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${
            viewMode === 'list'
              ? 'bg-primary text-primary-foreground'
              : 'text-muted-foreground hover:bg-muted'
          }`}
        >
          List
        </button>
        <button
          role="tab"
          aria-selected={viewMode === 'calendar'}
          onClick={() => setViewMode('calendar')}
          className={`px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${
            viewMode === 'calendar'
              ? 'bg-primary text-primary-foreground'
              : 'text-muted-foreground hover:bg-muted'
          }`}
        >
          Calendar
        </button>
      </div>

      {/* Calendar View */}
      {viewMode === 'calendar' ? (
        <RepairCalendarView />
      ) : (
        /* List View — table section */
        <section
          className="relative z-[1] glass-card glass-card-accent overflow-hidden animate-fade-in-up"
          style={{ animationDelay: '.15s' }}
          aria-label="Repairs table"
        >
          <div className="absolute inset-0 rounded-2xl bg-gradient-to-br from-cyan-500/[.03] via-transparent to-violet-500/[.03] pointer-events-none" aria-hidden />

          {/* Section header */}
          <div className="relative z-[1] flex items-center gap-2.5 px-5 pt-5 pb-3">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-cyan-500/20 to-violet-600/15 ring-1 ring-white/10 shadow-[0_0_18px_rgba(34,211,238,.18)]">
              <Wrench size={15} className="text-cyan-300/90" strokeWidth={2.2} />
            </div>
            <div className="min-w-0">
              <h2 className="text-sm font-semibold tracking-wide text-foreground/90">
                Repairs
              </h2>
              <p className="mt-0.5 text-[11px] text-muted-foreground/80">
                Click a row to view details
              </p>
            </div>
          </div>
          <div className="relative z-[1] h-px mx-5 animated-underline" aria-hidden />

          {/* Body */}
          <div className="relative z-[1] p-5">
            {error && (
              <div className="mb-4 rounded-md border border-red-300/30 bg-red-500/10 px-3 py-2 text-sm text-red-200">
                {error}
              </div>
            )}

            {loading ? (
              <TableSkeleton />
            ) : repairs.length === 0 ? (
              <EmptyState
                hasFilters={!!hasActiveFilters}
                onAdd={() => setShowIntakeModal(true)}
                onClearFilters={() => {
                  setFilters({ status: undefined, assignedTo: undefined, pickupDate: undefined })
                  setCurrentPage(1)
                }}
              />
            ) : (
              <>
                <RepairsTable
                  repairs={repairs}
                  workers={workers}
                  expandedId={expandedId}
                  detailCache={detailCache}
                  detailLoading={detailLoading}
                  detailError={detailError}
                  onRowClick={handleRowClick}
                  onRetryDetail={() => {
                    if (expandedId) void loadDetail(expandedId)
                  }}
                  onOpenRepair={handleOpenRepair}
                />

                {/* Pagination */}
                {totalPages > 1 && (
                  <div className="flex items-center justify-between mt-4">
                    <p className="text-sm text-muted-foreground">
                      Showing page {currentPage} of {totalPages} ({repairs.length} repairs)
                    </p>
                    <div className="flex gap-2">
                      <button
                        onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                        disabled={currentPage === 1}
                        className="px-3 py-1.5 text-sm border rounded-lg disabled:opacity-50 hover:bg-muted"
                      >
                        Previous
                      </button>
                      <button
                        onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                        disabled={currentPage === totalPages}
                        className="px-3 py-1.5 text-sm border rounded-lg disabled:opacity-50 hover:bg-muted"
                      >
                        Next
                      </button>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </section>
      )}

      {/* Intake Modal */}
      <RepairIntakeModal
        open={showIntakeModal}
        onOpenChange={(open) => setShowIntakeModal(open)}
        onSuccess={() => {
          loadRepairs()
          setCurrentPage(1)
        }}
      />
    </div>
  )
}

// ============================================================================
// Sub-components
// ============================================================================

interface KpiCardProps {
  label: string
  value: string
  sub: string
  accent: 'cyan' | 'emerald' | 'violet' | 'amber' | 'rose'
}

const KPI_ACCENT: Record<KpiCardProps['accent'], {
  border: string
  glow: string
  text: string
}> = {
  cyan: {
    border: 'border-l-cyan-400',
    glow: 'hover:shadow-neon-cyan',
    text: 'text-cyan-300/95',
  },
  emerald: {
    border: 'border-l-emerald-400',
    glow: 'hover:shadow-neon-green',
    text: 'text-emerald-300/95',
  },
  violet: {
    border: 'border-l-violet-400',
    glow: 'hover:shadow-neon-violet',
    text: 'text-violet-300/95',
  },
  amber: {
    border: 'border-l-amber-400',
    glow: 'hover:shadow-neon-amber',
    text: 'text-amber-300/95',
  },
  rose: {
    border: 'border-l-rose-400',
    glow: 'hover:shadow-neon-rose',
    text: 'text-rose-300/95',
  },
}

function KpiCard({ label, value, sub, accent }: KpiCardProps) {
  const c = KPI_ACCENT[accent]
  return (
    <div
      className={cn(
        'glass-card glass-card-accent group relative overflow-hidden border-l-4 p-5 animate-fade-in-up',
        c.border,
        c.glow
      )}
    >
      {/* Soft color halo behind card */}
      <div
        className="absolute inset-0 rounded-2xl bg-gradient-to-br from-white/[.04] to-transparent opacity-50 group-hover:opacity-80 transition-opacity pointer-events-none"
        aria-hidden
      />
      <div className="relative z-[1]">
        <p className="text-[10.5px] font-bold uppercase tracking-[.14em] text-muted-foreground/70">
          {label}
        </p>
        <p
          className={cn(
            'mt-2 text-[1.7rem] font-extrabold leading-none tabular-nums value-flash',
            c.text
          )}
        >
          {value}
        </p>
        <p className="mt-2 text-[10.5px] font-medium tracking-wide text-muted-foreground/60">
          {sub}
        </p>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// RepairsTable — sales-style table with inline row expand
// ---------------------------------------------------------------------------

interface RepairsTableProps {
  repairs: RepairDetailWithCustomer[]
  workers: WorkerOption[]
  expandedId: string | null
  detailCache: Map<string, RepairDetailResponse>
  detailLoading: Set<string>
  detailError: string | null
  onRowClick: (id: string) => void
  onRetryDetail: () => void
  onOpenRepair: (id: string) => void
}

function RepairsTable({
  repairs,
  workers,
  expandedId,
  detailCache,
  detailLoading,
  detailError,
  onRowClick,
  onRetryDetail,
  onOpenRepair,
}: RepairsTableProps) {
  return (
    <div className="overflow-hidden rounded-xl border border-white/[.06]">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-white/[.06] bg-white/[.02]">
            <th className="w-8 px-2 py-2.5" aria-label="Expand row" />
            <th className="px-3 py-2.5 text-left text-[10.5px] font-bold uppercase tracking-[.12em] text-muted-foreground/70">
              Status
            </th>
            <th className="px-3 py-2.5 text-left text-[10.5px] font-bold uppercase tracking-[.12em] text-muted-foreground/70">
              Customer
            </th>
            <th className="px-3 py-2.5 text-left text-[10.5px] font-bold uppercase tracking-[.12em] text-muted-foreground/70">
              Bicycle
            </th>
            <th className="px-3 py-2.5 text-left text-[10.5px] font-bold uppercase tracking-[.12em] text-muted-foreground/70">
              Assigned To
            </th>
            <th className="px-3 py-2.5 text-left text-[10.5px] font-bold uppercase tracking-[.12em] text-muted-foreground/70">
              Planned Date
            </th>
            <th className="px-3 py-2.5 text-left text-[10.5px] font-bold uppercase tracking-[.12em] text-muted-foreground/70">
              Pickup Date
            </th>
          </tr>
        </thead>
        <tbody>
          {repairs.map((repair) => {
            const isExpanded = expandedId === repair.id
            return (
              <RepairRowGroup
                key={repair.id}
                repair={repair}
                workers={workers}
                isExpanded={isExpanded}
                detail={detailCache.get(repair.id) ?? null}
                detailLoading={detailLoading.has(repair.id)}
                detailError={isExpanded ? detailError : null}
                onRowClick={() => onRowClick(repair.id)}
                onRetryDetail={onRetryDetail}
                onOpenRepair={onOpenRepair}
              />
            )
          })}
        </tbody>
      </table>
    </div>
  )
}

// ---------------------------------------------------------------------------
// RepairRowGroup — one collapsible row + its optional expanded detail panel
// ---------------------------------------------------------------------------

interface RepairRowGroupProps {
  repair: RepairDetailWithCustomer
  workers: WorkerOption[]
  isExpanded: boolean
  detail: RepairDetailResponse | null
  detailLoading: boolean
  detailError: string | null
  onRowClick: () => void
  onRetryDetail: () => void
  onOpenRepair: (id: string) => void
}

function RepairRowGroup({
  repair,
  workers,
  isExpanded,
  detail,
  detailLoading,
  detailError,
  onRowClick,
  onRetryDetail,
  onOpenRepair,
}: RepairRowGroupProps) {
  return (
    <>
      <tr
        onClick={onRowClick}
        className={cn(
          'cursor-pointer border-b border-white/[.04] transition-colors',
          isExpanded ? 'bg-white/[.04]' : 'hover:bg-white/[.03]',
        )}
      >
        {/* Chevron toggle */}
        <td className="px-2 py-2.5 align-middle">
          <ChevronDown
            size={14}
            className={cn(
              'text-muted-foreground/60 transition-transform',
              isExpanded && 'rotate-180 text-cyan-300',
            )}
          />
        </td>

        {/* Status Badge */}
        <td className="px-3 py-2.5 align-middle">
          <span
            className={cn(
              'inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-medium',
              STATUS_COLORS[repair.status]
            )}
          >
            {repair.status
              .replace('_', ' ')
              .replace(/\b\w/g, (c) => c.toUpperCase())}
          </span>
        </td>

        {/* Customer Name */}
        <td className="px-3 py-2.5 align-middle text-[12.5px] text-white/85">
          {repair.customerName || '—'}
        </td>

        {/* Bicycle Info */}
        <td className="px-3 py-2.5 align-middle text-[12.5px] text-white/80">
          <div>{repair.bicycleBrand}</div>
          <div className="text-[11.5px] text-muted-foreground/80">
            {repair.bicycleModel}
            {repair.bicycleColor ? ` · ${repair.bicycleColor}` : ''}
          </div>
        </td>

        {/* Assigned Worker */}
        <td className="px-3 py-2.5 align-middle text-[12.5px] text-white/80">
          <div className="flex items-center gap-1.5 text-muted-foreground/90">
            <User size={13} />
            {getWorkerName(repair.assignedTo, workers)}
          </div>
        </td>

        {/* Planned Date */}
        <td className="px-3 py-2.5 align-middle text-[12.5px] text-white/80 tabular-nums">
          <div className="flex items-center gap-1.5 text-muted-foreground/90">
            <Calendar size={13} />
            {formatDate(repair.plannedDate)}
          </div>
        </td>

        {/* Pickup Date */}
        <td className="px-3 py-2.5 align-middle text-[12.5px] text-white/80 tabular-nums">
          <div className="flex items-center gap-1.5 text-muted-foreground/90">
            <Calendar size={13} />
            {formatDate(repair.pickupDate)}
          </div>
        </td>
      </tr>
      {isExpanded && (
        <tr className="border-b border-white/[.04] bg-white/[.02]">
          <td colSpan={7} className="p-0">
            <RepairRowExpandPanel
              detail={detail}
