/**
 * useRepairDetailCache — lazy-loaded cache for the enriched repair detail.
 *
 * Mirrors the `detailCache` / `detailLoading` / `detailError` shape exposed by
 * `useSalesHistory`, so the list page can fetch `/api/repairs/:id` on first
 * row expand and reuse the result on subsequent toggles.
 *
 * - First call to `loadDetail(id)` triggers the fetch.
 * - While in flight, `id` is added to `detailLoading`.
 * - On success, the response is stored in `detailCache` and `detailLoading` is cleared.
 * - On failure, the error is exposed via `detailError`; the cache is untouched so a retry re-fetches.
 * - Subsequent calls for the same id return the cached value (or `null` if still loading).
 */

import { useCallback, useState } from 'react'
import { getRepair, type RepairDetailResponse } from '../api.js'

// ---------------------------------------------------------------------------
// Hook contract
// ---------------------------------------------------------------------------

export interface UseRepairDetailCacheReturn {
  /** Cached responses keyed by repair id. */
  detailCache: Map<string, RepairDetailResponse>
  /** Set of repair ids whose detail is currently being fetched. */
  detailLoading: Set<string>
  /**
   * Error message from the most recent failed load. Cleared on each new
   * fetch attempt. Single-row expansion means this is effectively scoped to
   * the currently-expanded row.
   */
  detailError: string | null
  /**
   * Fetch (or return cached) detail for `id`.
   * Returns the cached value on hit, the freshly-fetched detail on miss, or
   * `null` if a fetch is already in flight or the request failed.
   */
  loadDetail: (id: string) => Promise<RepairDetailResponse | null>
}

export function useRepairDetailCache(): UseRepairDetailCacheReturn {
  const [detailCache, setDetailCache] = useState<Map<string, RepairDetailResponse>>(new Map())
  const [detailLoading, setDetailLoading] = useState<Set<string>>(new Set())
  const [detailError, setDetailError] = useState<string | null>(null)

  const loadDetail = useCallback(
    async (id: string): Promise<RepairDetailResponse | null> => {
      // Cache hit — return immediately
      const cached = detailCache.get(id)
      if (cached) return cached
      // Already in flight — don't double-fetch
      if (detailLoading.has(id)) return null

      setDetailLoading((prev) => {
        if (prev.has(id)) return prev
        const next = new Set(prev)
        next.add(id)
        return next
      })
      setDetailError(null)
      try {
        const detail = await getRepair(id)
        setDetailCache((prev) => {
          const next = new Map(prev)
          next.set(id, detail)
          return next
        })
        return detail
      } catch (err) {
        setDetailError(err instanceof Error ? err.message : 'Failed to load repair')
        return null
      } finally {
        setDetailLoading((prev) => {
          if (!prev.has(id)) return prev
          const next = new Set(prev)
          next.delete(id)
          return next
        })
      }
    },
    [detailCache, detailLoading],
  )

  return { detailCache, detailLoading, detailError, loadDetail }
}

/**
 * useRepairsForWeek — Data hook for the week calendar view.
 *
 * Fetches active repairs for a 7-day range (Mon–Sun) and provides
 * prev/next/today navigation. Returns epoch-ms boundaries so that
 * the UI can distribute repair cards into day columns.
 */

import { useState, useEffect, useCallback } from 'react'
import type { RepairDetailWithCustomer } from '../types.js'
import { getRepairsForWeek } from '../api.js'

// ---------------------------------------------------------------------------
// Week boundary helpers (Mon–Sun, local time)
// ---------------------------------------------------------------------------

/** Get Monday 00:00:00.000 of the week containing `date` */
function mondayOf(date: Date): number {
  const d = new Date(date)
  const day = d.getDay() // 0=Sun, 1=Mon ...
  const diffToMonday = day === 0 ? -6 : 1 - day
  d.setDate(d.getDate() + diffToMonday)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

// ---------------------------------------------------------------------------
// Hook interface
// ---------------------------------------------------------------------------

export interface UseRepairsForWeekOptions {
  /** Optional anchor date. Defaults to today. */
  initialDate?: Date
}

export interface UseRepairsForWeekReturn {
  repairs: RepairDetailWithCustomer[]
  weekStart: number // Monday 00:00:00.000 (epoch ms)
  weekEnd: number   // Sunday 23:59:59.999 (epoch ms)
  isLoading: boolean
  error: string | null
  goPrev: () => void
  goNext: () => void
  goToday: () => void
  refetch: () => void
}

/**
 * Fetches repairs for a week range and provides navigation controls.
 */
export function useRepairsForWeek(options?: UseRepairsForWeekOptions): UseRepairsForWeekReturn {
  const anchorDate = options?.initialDate ?? new Date()

  // Track the current Monday to enable prev/next navigation
  const [weekMonday, setWeekMonday] = useState<number>(() => mondayOf(anchorDate))

  // Refetch trigger — incrementing this forces a re-fetch without changing week range
  const [refetchKey, setRefetchKey] = useState(0)

  const [repairs, setRepairs] = useState<RepairDetailWithCustomer[]>([])
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const [error, setError] = useState<string | null>(null)

  // Compute week boundaries from the current Monday anchor
  const weekStart = weekMonday
  const weekEnd = (() => {
    const sun = new Date(weekMonday)
    sun.setDate(sun.getDate() + 6)
    sun.setHours(23, 59, 59, 999)
    return sun.getTime()
  })()

  // Fetch repairs whenever the week range changes
  useEffect(() => {
    let cancelled = false

    const fetchRepairs = async () => {
      setIsLoading(true)
      setError(null)

      try {
        const result = await getRepairsForWeek(weekStart, weekEnd)
        if (!cancelled) {
          setRepairs(result.repairs)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to fetch repairs')
          setRepairs([])
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchRepairs()

    return () => {
      cancelled = true
    }
  }, [weekStart, weekEnd, refetchKey])

  // Navigation handlers — shift the Monday anchor by ±7 days
  const goPrev = useCallback(() => {
    setWeekMonday((prev) => prev - 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goNext = useCallback(() => {
    setWeekMonday((prev) => prev + 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goToday = useCallback(() => {
    setWeekMonday(mondayOf(new Date()))
  }, [])

  // Force a re-fetch of the current week's repairs (e.g. after rescheduling)
  const refetch = useCallback(() => {
    setRefetchKey((prev) => prev + 1)
  }, [])

  return { repairs, weekStart, weekEnd, isLoading, error, goPrev, goNext, goToday, refetch }
}

